<?php
namespace App\Services;
use App\Models\{CommitteeFormation,Documento,DocumentoCambio};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Support\Facades\Storage;
class CommitteeFormationActService {
 public function render(CommitteeFormation $formation):string{$formation->load(['committee.company','period.members.employee','period.roles.member.employee','election.formationProcess']);return Pdf::loadView('pdf.committee_formation',compact('formation'))->output();}
 public function finalize(CommitteeFormation $formation,int $userId):void{$content=$this->render($formation);$path='documentos/comites/'.str_replace(['/', '\\'],'-',$formation->act_number).'.pdf';Storage::disk('public')->put($path,$content);$number=(Documento::max('id')??0)+1;$document=Documento::create(['titulo'=>'Acta de conformación '.$formation->committee->name,'descripcion'=>'Acta oficial de conformación '.$formation->act_number,'categoria'=>'Formatos y Registros','archivo_ruta'=>$path,'extension_archivo'=>'pdf','subido_por'=>$userId,'codigo'=>'SST-F-'.str_pad($number,2,'0',STR_PAD_LEFT),'nombre_archivo'=>basename($path),'fecha_vigencia_inicio'=>$formation->effective_from,'fecha_vigencia_fin'=>$formation->effective_to,'version'=>'1.0','tipo_accion'=>'Nuevo']);DocumentoCambio::create(['documento_id'=>$document->id,'version'=>'1.0','fecha_vigencia_inicio'=>$formation->effective_from,'fecha_vigencia_fin'=>$formation->effective_to,'tipo_cambio'=>'Nuevo','observaciones'=>'Acta final generada automáticamente durante la conformación del comité.','registrado_por'=>$userId]);$formation->update(['act_status'=>'final','act_path'=>$path,'act_hash'=>hash('sha256',$content),'documento_id'=>$document->id]);}
}
